242	    /**
243	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
244	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
245	     * Validation already rejects {@code null} values and the pattern-constrained fields
246	     * when blank, but {@code address} and {@code city} have no pattern, so a
247	     * whitespace-only value would otherwise slip through.
248	     *
249	     * @param ownerFieldsDto the submitted owner fields
250	     * @throws RequiredFieldsMissingException if any required field is missing or blank
251	     */
252	    /**
253	     * Common street-type abbreviations expanded during address normalization. Keys are the
254	     * upper-cased abbreviation tokens; values are their canonical expansions.
255	     */
256	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
257	        "ST", "STREET",
258	        "RD", "ROAD",
259	        "AVE", "AVENUE");
260	
261	    /**
262	     * Normalizes the submitted address on create, accepting either the structured form
263	     * ({@code addressLine1} plus an optional {@code addressLine2}) or the flat {@code address}
264	     * form retained for backward compatibility. Each supplied field is canonicalized the same way
265	     * (trimmed, internal whitespace collapsed to a single space, upper-cased, and common
266	     * street-type abbreviations expanded — see {@link #ADDRESS_ABBREVIATIONS}), and the normalized
267	     * values are written back onto the request.
268	     *
269	     * <p>The structured fields are preferred when present: when a non-blank {@code addressLine1} is
270	     * supplied, the flat {@code address} is set to the composed value — the normalized
271	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended
272	     * when an {@code addressLine2} is present — otherwise it keeps the normalized flat value. The
273	     * composed {@code address} is therefore persisted, echoed back, and used by everything that
274	     * reads the flat address. A blank/absent value in every form leaves {@code address} blank so the
275	     * required-field check can report it as missing.
276	     *
277	     * @param ownerFieldsDto the submitted owner fields
278	     */
279	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
280	        String addressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
281	        String addressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
282	        String flat = normalizeAddress(ownerFieldsDto.getAddress());
283	        ownerFieldsDto.setAddressLine1(addressLine1);
284	        ownerFieldsDto.setAddressLine2(addressLine2);
285	        String composed;
286	        if (addressLine1 != null && !addressLine1.isBlank()) {
287	            composed = (addressLine2 != null && !addressLine2.isBlank())
288	                ? addressLine1 + " " + addressLine2
289	                : addressLine1;
290	        }
291	        else {
292	            composed = flat;
293	        }
294	        ownerFieldsDto.setAddress(composed);
295	    }
296	
297	    /**
298	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
299	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
300	     * expanded to its full form. A {@code null} value is returned unchanged.
301	     *
302	     * @param raw the address to canonicalize, possibly {@code null}
303	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
304	     */
305	    private static String normalizeAddress(String raw) {
306	        if (raw == null) {
307	            return null;
308	        }
309	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
310	        if (collapsed.isEmpty()) {
311	            return collapsed;
312	        }
313	        String[] tokens = collapsed.split(" ");
314	        StringBuilder sb = new StringBuilder(collapsed.length());
315	        for (int i = 0; i < tokens.length; i++) {
316	            if (i > 0) {
317	                sb.append(' ');
318	            }
319	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
320	        }
321	        return sb.toString();
322	    }
323	
324	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
325	        List<String> errors = new ArrayList<>();
326	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
327	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
328	        requireText("address", ownerFieldsDto.getAddress(), errors);
329	        requireText("city", ownerFieldsDto.getCity(), errors);
330	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
331	        if (!errors.isEmpty()) {
332	            throw new RequiredFieldsMissingException(errors);
333	        }
334	    }
335	
336	    private static void requireText(String field, String value, List<String> errors) {
337	        if (value == null || value.isBlank()) {
338	            errors.add(field);
339	        }
340	    }
341	
342	    /**
343	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
344	     * postcode against the owner's city. A region absent from this table (i.e. a city whose region
345	     * is {@code 'UNKNOWN'}) imposes no range, so any 4-digit postcode is accepted there.
346	     */
347	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
348	        "NSW", new int[] {2000, 2099},
349	        "VIC", new int[] {3000, 3099},
350	        "QLD", new int[] {4000, 4099});
351	
352	    /**
353	     * Validates the submitted {@code postcode} only when present. The field is optional, so a
354	     * {@code null} value is accepted. When present it has already been constrained to four digits
355	     * by Bean Validation; here it is additionally checked against the owner's city: for a city
356	     * whose region is known (see {@link org.springframework.samples.petclinic.mapper.LocalityLookup}),
357	     * the postcode must fall within that region's inclusive range
358	     * ({@link #REGION_POSTCODE_RANGE}); a city with no known region accepts any 4-digit value.
359	     *
360	     * @param ownerFieldsDto the submitted owner fields (city already validated as present)
361	     * @throws InvalidPostcodeException with a 400 status if the postcode is out of range for the
362	     *                                  city's region
363	     */
364	    private static void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
365	        String postcode = ownerFieldsDto.getPostcode();
366	        if (postcode == null) {
367	            return;
368	        }
369	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
370	            .regionFor(ownerFieldsDto.getCity());
371	        int[] range = REGION_POSTCODE_RANGE.get(region);
372	        if (range == null) {
373	            return;
374	        }
375	        int value = Integer.parseInt(postcode);
376	        if (value < range[0] || value > range[1]) {
377	            throw new InvalidPostcodeException(postcode);
378	        }
379	    }
380	
381	    /**
382	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
383	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
384	     * and echoed back in that form.
385	     *
386	     * @param ownerFieldsDto the submitted owner fields
387	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
388	     *                                        valid E.164 number
389	     */
390	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
391	        String e164 = toE164(ownerFieldsDto.getTelephone());
392	        if (e164 == null) {
393	            throw new RequiredFieldsMissingException(List.of("telephone"));
394	        }
395	        ownerFieldsDto.setTelephone(e164);
396	    }
397	
398	    /**
399	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
400	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
401	     * and country code are present they are kept; otherwise country code {@code '+61'} is
402	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
403	     * must contain 8 to 15 digits after the {@code '+'}, and for the recognised country codes
404	     * the national-number length must match the country: {@code '+61'} (Australia) requires
405	     * exactly 9 national digits and {@code '+1'} (NANP) requires exactly 10.
406	     *
407	     * @param raw the submitted telephone, possibly {@code null}
408	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
409	     */
410	    private static String toE164(String raw) {
411	        if (raw == null) {
412	            return null;
413	        }
414	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
415	        String digits;
416	        if (cleaned.startsWith("+")) {
417	            digits = cleaned.substring(1);
418	        } else {
419	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
420	            digits = "61" + national;
421	        }
422	        if (!digits.matches("[0-9]{8,15}")) {
423	            return null;
424	        }
425	        if (digits.startsWith("61")) {
426	            // Australia: exactly 9 national digits after the '+61' country code.
427	            if (digits.length() - 2 != 9) {
428	                return null;
429	            }
430	        } else if (digits.startsWith("1")) {
431	            // NANP: exactly 10 national digits after the '+1' country code.
432	            if (digits.length() - 1 != 10) {
433	                return null;
434	            }
435	        }
436	        return "+" + digits;
437	    }
438	
439	    /**
440	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
441	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
442	     * each stored owner's telephone is normalized the same way before comparison so differing
443	     * input formats collapse to the same value.
444	     *
445	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
446	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
447	     *                                     same E.164 telephone
448	     */
449	    /**
450	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
451	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
452	     * the parts may contain whitespace or a second {@code @}.
453	     */
454	    private static final Pattern EMAIL_PATTERN =
455	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
456	
457	    /**
458	     * Disposable email domains that are not accepted for an owner's email. A create whose email
459	     * domain (the part after the {@code '@'}, compared case-insensitively) is on this blocklist is
460	     * rejected. Kept lower-cased to match the normalized email.
461	     */
462	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
463	        "mailinator.com",
464	        "tempmail.com",
465	        "guerrillamail.com");
466	
467	    /**
468	     * Normalizes the submitted email when present: the value is trimmed, required to be a
469	     * syntactically valid address, required not to use a disposable-email domain, and written back
470	     * lower-cased so it is persisted and echoed back in canonical form. A {@code null} email is
471	     * left untouched — the field is optional.
472	     *
473	     * @param ownerFieldsDto the submitted owner fields
474	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically
475	     *                               valid, or its domain is on the disposable-domain blocklist
476	     */
477	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
478	        String email = ownerFieldsDto.getEmail();
479	        if (email == null) {
480	            return;
481	        }
482	        String trimmed = email.strip();
483	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
484	            throw new InvalidEmailException(email);
485	        }
486	        String normalized = trimmed.toLowerCase(Locale.ROOT);
487	        String domain = normalized.substring(normalized.indexOf('@') + 1);
488	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
489	            throw new InvalidEmailException(email);
490	        }
491	        ownerFieldsDto.setEmail(normalized);
492	    }
493	
494	    /**
495	     * Rejects a create whose supplied {@code registrationDate} is later than the server's current
496	     * date. A registration may be back-dated but never post-dated. The check is made against the
497	     * value as supplied, before any defaulting or business-day roll (see
498	     * {@link #defaultRegistrationDate}); a {@code null} registration date is accepted (it defaults
499	     * to the server date).
500	     *
501	     * @param ownerFieldsDto the submitted owner fields
502	     * @throws FutureRegistrationDateException with a 400 status if the supplied registration date is
503	     *                                         after the server's current date
504	     */
505	    private static void rejectFutureRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
506	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
507	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
508	            throw new FutureRegistrationDateException(supplied);
509	        }
510	    }
511	
512	    /**
513	     * Establishes the effective registration date on create and rolls it onto a business day.
514	     * When the client does not supply a {@code registrationDate} it defaults to the server's
515	     * current date; the resulting date (supplied or defaulted) is then rolled forward to the
516	     * next Monday when it falls on a Saturday or Sunday (see {@link #toBusinessDay}). The
517	     * adjusted value is written back onto the request so it is persisted, echoed back in ISO
518	     * 'YYYY-MM-DD' format, and used by every value derived from the registration date (such as
519	     * the membership number's year segment and the daily create-limit).
520	     *
521	     * @param ownerFieldsDto the submitted owner fields
522	     */
523	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
524	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
525	        if (effective == null) {
526	            effective = LocalDate.now();
527	        }
528	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
529	    }
530	
531	    /**
532	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
533	     * following Monday; any weekday is returned unchanged.
534	     *
535	     * @param date the date to adjust
536	     * @return the same date when it is a weekday, otherwise the next Monday
537	     */
538	    private static LocalDate toBusinessDay(LocalDate date) {
539	        return switch (date.getDayOfWeek()) {
540	            case SATURDAY -> date.plusDays(2);
541	            case SUNDAY -> date.plusDays(1);
542	            default -> date;
543	        };
544	    }
545	
546	    /**
547	     * Assigns the owner's {@code customerCode} on create, formatted
548	     * {@code '<REGION>-<HASH8>'} where REGION is the region derived from the owner's postcode
549	     * (preferring the postcode range, falling back to the city — the same derivation that yields
550	     * the owner's {@code locality}, see
551	     * {@link org.springframework.samples.petclinic.mapper.LocalityLookup#regionFor(String, String)}),
552	     * and HASH8 is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
553	     * already-normalized (E.164) {@code telephone} concatenated with its {@code lastName} — e.g.
554	     * {@code 'NSW-A1B2C3D4'}. There is no per-city sequence: two owners in the same region share a
555	     * customer code only when their normalized telephone and last name both match.
556	     *
557	     * <p>When the computed customer code collides with an existing owner's {@code customerCode},
558	     * it is de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
559	     * makes it unique among the existing owners, so distinct owners always receive distinct codes.
560	     *
561	     * @param owner the owner being created (with its {@code postcode}, {@code city},
562	     *              {@code telephone} and {@code lastName} already set)
563	     */
564	    private void assignCustomerCode(Owner owner) {
565	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
566	            .regionFor(owner.getPostcode(), owner.getCity());
567	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
568	            .substring(0, 8).toUpperCase(Locale.ROOT);
569	        String base = region + "-" + hash8;
570	        Set<String> existing = this.clinicService.findAllOwners().stream()
571	            .map(Owner::getCustomerCode)
572	            .filter(Objects::nonNull)
573	            .collect(Collectors.toSet());
574	        String customerCode = base;
575	        for (int n = 2; existing.contains(customerCode); n++) {
576	            customerCode = base + "-" + n;
577	        }
578	        owner.setCustomerCode(customerCode);
579	    }
580	
581	    /**
582	     * Assigns the owner's {@code householdId} on create: a stable, deterministic identifier for
583	     * the household, the first 12 hex characters of the SHA-256 digest of the owner's normalized
584	     * {@code lastName} and {@code postcode} (see {@link #householdIdFor}). Because it is derived
585	     * purely from those two fields, every owner sharing a last name and postcode is assigned the
586	     * same value automatically — including one joining an existing household via
587	     * {@code sharesHousehold} — independent of create order.
588	     *
589	     * @param owner the owner being created (with its {@code lastName} and {@code postcode} already set)
590	     */
591	    private void assignHouseholdId(Owner owner) {
592	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
593	    }
594	
595	    /**
596	     * Derives the deterministic {@code householdId} for the given {@code lastName} and
597	     * {@code postcode}: the first 12 hex characters of the SHA-256 digest of the normalized
598	     * {@code lastName} (see {@link #collapse}) concatenated with a {@code '|'} and the
599	     * {@code postcode} (empty when absent). Because it is derived purely from those two fields,
600	     * every owner sharing a last name and postcode receives the same value, independent of create
601	     * order. Shared by {@link #assignHouseholdId} (which persists it), {@link #identityKeyFor}
602	     * (which folds it into the identity key for duplicate detection) and
603	     * {@link #rejectDuplicateHousehold} (which blocks a second owner in the same household).
604	     *
605	     * @param lastName the owner's last name
606	     * @param postcode the owner's postcode, possibly {@code null}
607	     * @return the derived household id
608	     */
609	    private static String householdIdFor(String lastName, String postcode) {
610	        String key = collapse(lastName) + "|" + (postcode == null ? "" : postcode);
611	        return sha256Hex(key).substring(0, 12);
612	    }
613	
614	    /**
615	     * Rejects a create whose computed {@code householdId} (derived from {@code lastName} and
616	     * {@code postcode}, see {@link #householdIdFor}) already belongs to an existing owner, unless
617	     * the request opts in via {@code sharesHousehold}. Because the household is keyed on
618	     * {@code (lastName, postcode)}, a second owner sharing both is the same household: it is
619	     * rejected with a 409 as a household duplicate unless it declares {@code sharesHousehold}, in
620	     * which case it is created as a declared household member. The scan is taken over the existing
621	     * owners before this one is persisted.
622	     *
623	     * @param ownerFieldsDto the submitted owner fields ({@code lastName} and {@code postcode} set)
624	     * @throws DuplicateHouseholdException with a 409 status if the household already exists and the
625	     *                                     request did not opt in via {@code sharesHousehold}
626	     */
627	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
628	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
629	            return;
630	        }
631	        String householdId = householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
632	        boolean duplicate = this.clinicService.findAllOwners().stream()
633	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
634	        if (duplicate) {
635	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
636	        }
637	    }
638	
639	    /**
640	     * Assigns the owner's {@code householdMemberCount} on create: the number of owners in this
641	     * owner's household — those already sharing its {@code householdId} plus this owner itself —
642	     * after this create. Because {@code householdId} is derived from the owner's {@code lastName}
643	     * and {@code postcode} (see {@link #assignHouseholdId}), the count reflects every
644	     * owner registered to the same household, including those who joined via {@code sharesHousehold}.
645	     * The count is taken before this owner is persisted, so it is one more than the number of
646	     * existing household members.
647	     *
648	     * @param owner the owner being created (with its {@code householdId} already assigned)
649	     */
650	    private void assignHouseholdMemberCount(Owner owner) {
651	        String householdId = owner.getHouseholdId();
652	        long existing = this.clinicService.findAllOwners().stream()
653	            .filter(other -> householdId != null && householdId.equals(other.getHouseholdId()))
654	            .count();
655	        owner.setHouseholdMemberCount((int) (existing + 1));
656	    }
657	
658	    /**
659	     * Assigns the owner's {@code namesakeCount} on create: the number of existing owners that
660	     * already share this owner's {@code firstName} and {@code lastName}, compared
661	     * case-insensitively. The count is taken before this owner is persisted, so it reflects only
662	     * pre-existing namesakes.
663	     *
664	     * @param owner the owner being created (with its {@code firstName} and {@code lastName} already set)
665	     */
666	    private void assignNamesakeCount(Owner owner) {
667	        String firstName = owner.getFirstName();
668	        String lastName = owner.getLastName();
669	        long count = this.clinicService.findAllOwners().stream()
670	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
671	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
672	            .count();
673	        owner.setNamesakeCount((int) count);
674	    }
675	
676	    /**
677	     * Assigns the owner's {@code membershipNumber} on create, formatted
678	     * {@code '<customerCode>-M<YY>'} where customerCode is the owner's already-assigned customer
679	     * code and YY is the last two digits of the {@code registrationDate} year, zero-padded
680	     * (e.g. {@code 'NSW-A1B2C3D4-M26'}). Derived purely from the owner's own fields, so both
681	     * {@link #assignCustomerCode} and {@link #defaultRegistrationDate} must run first.
682	     *
683	     * @param owner the owner being created (with its {@code customerCode} and
684	     *              {@code registrationDate} already set)
685	     */
686	    private void assignMembershipNumber(Owner owner) {
687	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
688	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
689	    }
690	
691	    /**
692	     * The number of owners that must already carry a registration date before a subsequent
693	     * create for that same day is flagged with a bulk-signup warning. The warning is raised
694	     * once the count of owners already registered on that day <em>exceeds</em> this value.
695	     */
696	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
697	
698	    /**
699	     * Assigns the owner's {@code bulkSignupWarning} on create: {@code true} when more than
700	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry this owner's (business-day
701	     * adjusted) {@code registrationDate}, otherwise {@code false}. The count is taken over the
702	     * existing owners before this one is persisted, so it reflects only the owners already
703	     * created for that day (matching the accumulation used by {@link #rejectDailyLimit}).
704	     *
705	     * @param owner the owner being created (with its {@code registrationDate} already set)
706	     */
707	    private void assignBulkSignupWarning(Owner owner) {
708	        LocalDate registrationDate = owner.getRegistrationDate();
709	        long count = this.clinicService.findAllOwners().stream()
710	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
711	            .count();
712	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
713	    }
714	
715	    /**
716	     * Assigns the owner's soft-match duplicate flags on create. The create has already passed
717	     * {@link #rejectDuplicateIdentity} and {@link #rejectDuplicateHousehold}, so this owner is not
718	     * a hard duplicate. A declared household member (one that opted in via {@code sharesHousehold})
719	     * is never flagged: it is an acknowledged member of the household, not a suspected duplicate,
720	     * so {@code possibleDuplicate} is {@code false}. Otherwise it is a <em>possible</em> duplicate
721	     * when an existing owner shares its {@code lastName} (compared case-insensitively) and its
722	     * {@code postcode} but has a <em>different</em> normalized {@code telephone}:
723	     * {@code possibleDuplicate} is set {@code true} and {@code possibleDuplicateOf} to that owner's
724	     * id (the earliest such owner by id when several match). Otherwise {@code possibleDuplicate} is
725	     * {@code false} and {@code possibleDuplicateOf} is left unset. The scan is taken over the
726	     * existing owners before this one is persisted.
727	     *
728	     * @param owner the owner being created (with its {@code lastName}, {@code postcode} and
729	     *              already-normalized {@code telephone} set)
730	     * @param declaredHouseholdMember whether the request opted in via {@code sharesHousehold}
731	     */
732	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
733	        if (declaredHouseholdMember) {
734	            owner.setPossibleDuplicate(false);
735	            owner.setPossibleDuplicateOf(null);
736	            return;
737	        }
738	        String lastName = owner.getLastName();
739	        String postcode = owner.getPostcode();
740	        String telephone = owner.getTelephone();
741	        Integer matchId = null;
742	        if (lastName != null && postcode != null && telephone != null) {
743	            matchId = this.clinicService.findAllOwners().stream()
744	                .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
745	                .filter(existing -> postcode.equals(existing.getPostcode()))
746	                .filter(existing -> !telephone.equals(existing.getTelephone()))
747	                .map(Owner::getId)
748	                .filter(id -> id != null)
749	                .min(Integer::compareTo)
750	                .orElse(null);
751	        }
752	        owner.setPossibleDuplicate(matchId != null);
753	        owner.setPossibleDuplicateOf(matchId);
754	    }
755	
756	    /**
757	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
758	     *
759	     * @param value the string to hash
760	     * @return the 64-character lower-case hex digest
761	     */
762	    private static String sha256Hex(String value) {
763	        try {
764	            byte[] digest = MessageDigest.getInstance("SHA-256")
765	                .digest(value.getBytes(StandardCharsets.UTF_8));
766	            StringBuilder sb = new StringBuilder(digest.length * 2);
767	            for (byte b : digest) {
768	                sb.append(String.format("%02x", b));
769	            }
770	            return sb.toString();
771	        }
772	        catch (NoSuchAlgorithmException e) {
773	            throw new IllegalStateException("SHA-256 not available", e);
774	        }
775	    }
776	
777	    /**
778	     * Rejects a create whose whole derived {@code identityKey} already equals that of an existing
779	     * owner. This single key consolidates what used to be three separate duplicate checks
780	     * (telephone, email and household): the key is
781	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} (see
782	     * {@link #identityKeyFor}), and a create is a duplicate only when its <em>whole</em> key
783	     * matches an existing owner's. Because the telephone is part of the key, two members of the
784	     * same household (same {@code householdId}) with different telephones have different identity
785	     * keys and are both allowed; only an exact full-key match is rejected. The submitted telephone
786	     * and email have already been normalized by {@link #normalizeTelephone} and
787	     * {@link #normalizeEmail}, and each existing owner's key is computed the same way so differing
788	     * input formats collapse to the same value.
789	     *
790	     * @param ownerFieldsDto the submitted owner fields (telephone and email already normalized)
791	     * @throws DuplicateIdentityException with a 409 status if another owner already has the same
792	     *                                    whole identity key
793	     */
794	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
795	        String identityKey = identityKeyFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode(),
796	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail());
797	        boolean duplicate = this.clinicService.findAllOwners().stream()
798	            .map(owner -> identityKeyFor(owner.getLastName(), owner.getPostcode(),
799	                owner.getTelephone(), owner.getEmail()))
800	            .anyMatch(identityKey::equals);
801	        if (duplicate) {
802	            throw new DuplicateIdentityException(identityKey);
803	        }
804	    }
805	
806	    /**
807	     * Computes an owner's derived {@code identityKey} from its identity-bearing fields:
808	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. The telephone is
809	     * normalized to E.164 form (see {@link #toE164}), the email is lower-cased (empty when
810	     * absent), and the {@code householdId} is derived from the {@code lastName} and
811	     * {@code postcode} the same way {@link #assignHouseholdId} assigns it (see
812	     * {@link #householdIdFor}). Deriving every part canonically means two owners collide only when
813	     * their whole identities match, regardless of the exact input formats.
814	     *
815	     * @param lastName  the owner's last name
816	     * @param postcode  the owner's postcode
817	     * @param telephone the owner's telephone, in any format {@link #toE164} accepts
818	     * @param email     the owner's email, possibly {@code null}
819	     * @return the canonical identity key
820	     */
821	    private static String identityKeyFor(String lastName, String postcode, String telephone, String email) {
822	        String normalizedTelephone = toE164(telephone);
823	        String telephonePart = normalizedTelephone == null ? "" : normalizedTelephone;
824	        String emailPart = email == null ? "" : email.strip().toLowerCase(Locale.ROOT);
825	        return telephonePart + "|" + emailPart + "|" + householdIdFor(lastName, postcode);
826	    }
827	
828	    /**
829	     * The maximum number of owners permitted in a single city. A create is rejected once the
830	     * owner's city already contains this many owners.
831	     */
832	    private static final long CITY_CAPACITY = 50;
833	
834	    /**
835	     * Rejects a create whose {@code city} already contains {@link #CITY_CAPACITY} or more owners,
836	     * compared case-insensitively (matching {@link #assignCustomerCode}). The count is taken
837	     * before this owner is persisted.
838	     *
839	     * @param city the submitted city
840	     * @throws CityAtCapacityException with a 409 status if the city is already at capacity
841	     */
842	    private void rejectCityAtCapacity(String city) {
843	        long count = this.clinicService.findAllOwners().stream()
844	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
845	            .count();
846	        if (count >= CITY_CAPACITY) {
847	            throw new CityAtCapacityException(city);
848	        }
849	    }
850	
851	    /**
852	     * The maximum number of owners permitted to be created in a single day. A create is
853	     * rejected once this many owners already carry today's {@code registrationDate}.
854	     */
855	    private static final long DAILY_LIMIT = 100;
856	
857	    /**
858	     * Rejects a create once {@link #DAILY_LIMIT} or more owners already carry the given adjusted
859	     * business day as their {@code registrationDate}. The day counted against is this create's
860	     * effective registration date after the business-day roll (see {@link #defaultRegistrationDate}),
861	     * so owners are counted per adjusted business day. The count is taken before this owner is
862	     * persisted.
863	     *
864	     * @param businessDay the effective, business-day-adjusted registration date of this create
865	     * @throws DailyOwnerLimitExceededException with a 429 status if the day is already at the limit
866	     */
867	    private void rejectDailyLimit(LocalDate businessDay) {
868	        long count = this.clinicService.findAllOwners().stream()
869	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
870	            .count();
871	        if (count >= DAILY_LIMIT) {
872	            throw new DailyOwnerLimitExceededException(businessDay);
873	        }
874	    }
875	
876	    /**
877	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
878	     * every internal run of whitespace is collapsed to a single space, and the result is
879	     * lower-cased. A {@code null} value collapses to the empty string.
880	     *
881	     * @param value the value to canonicalize, possibly {@code null}
882	     * @return the collapsed, lower-cased value
883	     */
884	    private static String collapse(String value) {
885	        if (value == null) {
886	            return "";
887	        }
888	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
889	    }
890	
891	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
892	    @Override
893	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
894	        Owner owner = this.clinicService.findOwnerById(ownerId);
895	        if (owner != null) {
896	            Pet pet = owner.getPet(petId);
897	            if (pet != null) {
898	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
899	            }
900	        }
901	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
902	    }
903	}
